/deep/.ivu-modal-body {
  max-height: 623px;
  overflow: auto;
}
.list {
  padding-left: 8px;
  .item {
    margin-right: 11px;
    text-align: center;
    cursor: pointer;

    &.on {
      .pictrue {
        border-color: #1890ff;
      }
    }

    .name {
      color: #3d3d3d;
      font-size: 14px;
      margin: 12px 0;
    }

    &:nth-of-type(3n) {
      margin-right: 0;
    }
    .pictrue {
      width: 273px;
      height: 218px;
      background: #f5f5f5;
      border-radius: 4px;
      border: 1px solid #dddddd;
      position: relative;

      img {
        display: block;
      }

      .iconfont {
        position: absolute;
        right: -1px;
        bottom: -4px;
        color: #1890ff;
      }
    }
  }
}
.button-style {
  padding: 0 15px;
  margin-bottom: 20px;

  .title-tips {
    margin-right: 14px;
    color: #999;
    font-size: 12px;
    width: 82px;
  }

  .style-box {
    .bnt {
      width: 94px;
      height: 32px;
      background: #1890ff;
      border-radius: 4px;
      text-align: center;
      line-height: 32px;
      color: #fff;
      font-size: 12px;
      cursor: pointer;
    }
    .name {
      color: #999999;
      font-size: 12px;
      margin-left: 12px;
    }
  }
}
